import { AstroError } from "astro/errors";
import { AstroJSX, jsx } from "astro/jsx-runtime";
import { chunkToString, renderStreaming } from "astro/runtime/server/index.js";
export const slotName = (str) => str.trim().replace(/[-_]([a-z])/g, (_, w) => w.toUpperCase());
// NOTE: In practice, MDX components are always tagged with `__astro_tag_component__`, so the right renderer
// is used directly, and this check is not often used to return true.
export async function check(Component, props, { default: children = null, ...slotted } = {}) {
	if (typeof Component !== "function") return false;
	const slots = {};
	for (const [key, value] of Object.entries(slotted)) {
		const name = slotName(key);
		slots[name] = value;
	}
	try {
		const result = await Component({
			...props,
			...slots,
			children
		});
		return result[AstroJSX];
	} catch (e) {
		throwEnhancedErrorIfMdxComponent(e, Component);
	}
	return false;
}
export async function renderToStaticMarkup(Component, props = {}, { default: children = null, ...slotted } = {}) {
	const slots = {};
	for (const [key, value] of Object.entries(slotted)) {
		const name = slotName(key);
		slots[name] = value;
	}
	const { result } = this;
	try {
		// Render the MDX vnode tree through Astro's streaming engine, the same
		// fast path used by `.astro` pages. The chunks are collected into a
		// string because this renderer must return ready HTML to its caller
		// (`renderComponent`).
		let html = "";
		const destination = { write(chunk) {
			if (chunk instanceof Response) return;
			html += chunkToString(result, chunk);
		} };
		await renderStreaming(jsx(Component, {
			...props,
			...slots,
			children
		}), result, destination);
		return { html };
	} catch (e) {
		throwEnhancedErrorIfMdxComponent(e, Component);
		throw e;
	}
}
function throwEnhancedErrorIfMdxComponent(error, Component) {
	// if the exception is from an mdx component
	// throw an error
	if (Component[Symbol.for("mdx-component")]) {
		// if it's an existing AstroError, we don't need to re-throw, keep the original hint
		if (AstroError.is(error)) return;
		// Mimic the fields of the internal `AstroError` class (not from `astro/errors`) to
		// provide better title and hint for the error overlay
		error.title = error.name;
		error.hint = `This issue often occurs when your MDX component encounters runtime errors.`;
		throw error;
	}
}
const renderer = {
	name: "astro:jsx",
	check,
	renderToStaticMarkup
};
export default renderer;
